1|\chapter{100 以内的数}\label{ch:g1:tens}
2|=
3|一个一个地数一大堆东西太费时间。妙招是：
4|把物体每\emph{十}个捆成一捆，再数捆数。这
5|这就是 $100$ 以内的数的构成方法，也解释了它们
6|为什么要用两位数来写。
7|=
8|\section{十个一捆}
9|=
10|\begin{definition}[十位与个位]\label{def:g1:tens:def}
11|一个\emph{十}就是十个一捆。数 $34$ 表示 $3$
12|个十和 $4$ 个一：
13|\[
14|=
15|\]
16|左边的数字表示捆数，右边的数字表示单个的个数。
17|\end{definition}
18|=
19|\begin{omfigure}
20|\begin{tikzpicture}[scale=0.75]
21|  % three bundles of ten sticks, each tied with a rounded band
22|    \begin{scope}
23|    \begin{scope}[xshift=\b*2.4cm]
24|    \foreach \i in {0,...,9} \draw[omDef, very thick]
25|      ({0.16*\i},0) -- ({0.16*\i},1.7);
26|    \draw[omExo, thick, rounded corners=3pt]
27|      (-0.22,0.62) rectangle (1.66,1.05);
28|    \end{scope}
29|  }
30|  % four loose sticks
31|  \foreach \i in {0,...,3} \draw[omThm, very thick]
32|    (7.7+0.4*\i,0) -- (7.7+0.4*\i,1.7);
33|  \node[right, font=\small] at (9.7,0.85)
34|    {$3$ 捆和 $4$ 根小棒：$34$};
35|\end{tikzpicture}
36|=
37|{\small 三十四根小棒：三捆十根（每捆都用带子扎好）和
38|四根单独的小棒。不用一根一根数到 $34$！}
39|\end{omfigure}
